const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');menu.textContent=open?'×':'☰';nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');menu.textContent='☰'}));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open'))menu.click()});document.querySelectorAll('[data-program]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#interest').value=a.dataset.program}));document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const name=form.elements.name.value.trim();if(!name){form.elements.name.setCustomValidity('Please enter your name.');form.elements.name.reportValidity();return}const data=new FormData(form);const text=`Hello D Academy! I'd like to enquire about classes.\n\nName: ${name}\nPhone: ${data.get('phone')}\nInterested in: ${data.get('interest')}\n${data.get('message')?`Message: ${data.get('message')}\n`:''}\nPlease share batch timings, fees and trial availability.`;const url='https://wa.me/919999789009?text='+encodeURIComponent(text);window.open(url,'_blank','noopener,noreferrer');const status=document.querySelector('#form-status');status.replaceChildren(document.createTextNode('Your enquiry is ready. '));const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.textContent='Open WhatsApp';link.style.textDecoration='underline';status.append(link)});document.querySelector('#name').addEventListener('input',e=>e.target.setCustomValidity(''));if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-heading,.about-copy,.program,.gallery-grid,.contact-grid').forEach(el=>{el.classList.add('reveal');observer.observe(el)})}
const photoViewer=document.querySelector('#photo-viewer');document.querySelectorAll('[data-photo]').forEach(link=>link.addEventListener('click',event=>{if(!photoViewer.showModal)return;event.preventDefault();const img=link.querySelector('img');document.querySelector('#viewer-image').src=link.href;document.querySelector('#viewer-image').alt=img.alt;document.querySelector('#viewer-caption').textContent=link.dataset.caption;photoViewer.showModal()}));document.querySelector('.photo-close').addEventListener('click',()=>photoViewer.close());photoViewer.addEventListener('click',event=>{if(event.target===photoViewer){const r=photoViewer.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)photoViewer.close()} });
